#include "video_sampling.h"
namespace msf { SamplePlan make_sample_plan(double d){SamplePlan p;if(d<=0)return p;if(d<=10)p.intervalSec=1;else if(d<=60)p.intervalSec=2;else if(d<=240)p.intervalSec=4;else if(d<=960)p.intervalSec=8;else if(d<=3840)p.intervalSec=16;else p.intervalSec=32;for(double t=0;t<d;t+=p.intervalSec)p.timestamps.push_back(t);if(p.timestamps.empty()||p.timestamps.back()<d-.001)p.timestamps.push_back(d);return p;} }